INSERT INTO `tbl_testimonial` VALUES (1,NULL,'James Carter','Regular Client','Best fade I\'ve had in years. Clean shop, amazing attention to detail, and the booking system is so easy.',5,'frontend/images/luxury/customer.jpg',1,1,'2026-08-14 22:52:28','2026-10-14 03:53:16','2026-10-14 03:53:16'),(2,NULL,'Michael Reyes','Premium Package','Luxury vibe without being pretentious. Hot towel shave was incredible — I\'ll be back every month.',5,'frontend/images/luxury/customer2.jpg',2,1,'2026-08-14 22:52:28','2026-10-14 03:53:19','2026-10-14 03:53:19'),(3,NULL,'David Nguyen','Beard Specialist Fan','Friendly barbers who really listen. My beard has never looked this sharp. Highly recommend.',5,'frontend/images/luxury/customer3.jpg',3,1,'2026-08-14 22:52:28','2026-10-14 03:53:21','2026-10-14 03:53:21'),(11,50,'ZZ Audit B','Tester','Better',4,NULL,2,0,'2026-10-26 19:10:27','2026-10-26 19:10:28','2026-10-26 19:10:28'),(12,50,'ZZ Audit B','Tester','Better',4,NULL,2,0,'2026-10-26 19:11:10','2026-10-26 19:11:11','2026-10-26 19:11:11'),(13,50,'ZZ Audit B','Tester','Better',4,NULL,2,0,'2026-10-26 19:12:16','2026-10-26 19:12:17','2026-10-26 19:12:17'),(14,50,'ZZ Audit B','Tester','Better',4,NULL,2,0,'2026-10-26 19:16:43','2026-10-26 19:16:45','2026-10-26 19:16:45'),(15,50,'ZZ Audit B','Tester','Better',4,NULL,2,0,'2026-10-26 19:17:26','2026-10-26 19:17:28','2026-10-26 19:17:28'),(16,50,'ZZ Audit B','Tester','Better',4,NULL,2,0,'2026-10-26 19:19:23','2026-10-26 19:19:24','2026-10-26 19:19:24'),(17,50,'ZZ Audit B','Tester','Better',4,NULL,2,0,'2026-10-26 19:21:09','2026-10-26 19:21:10','2026-10-26 19:21:10'),(18,50,'ZZ Audit B','Tester','Better',4,NULL,2,0,'2026-10-26 19:22:58','2026-10-26 19:22:59','2026-10-26 19:22:59'),(19,50,'ZZ Audit B','Tester','Better',4,NULL,2,0,'2026-10-26 19:24:06','2026-10-26 19:24:08','2026-10-26 19:24:08'),(20,50,'ZZ Audit B','Tester','Better',4,NULL,2,0,'2026-10-26 19:26:41','2026-10-26 19:26:42','2026-10-26 19:26:42'),(21,50,'ZZ Audit B','Tester','Better'